        #else
        u16 move = gContestMons[eContestAI.contestantId].moves[i];
        #endif

        if (move == targetMove)
        {
            hasMove = TRUE;
            break;
        }
    }

    eContestAI.scriptResult = hasMove;
    gAIScriptPtr += 3;

